PLANNED = 434
MARKER = b"--- Your run record below this line"
PAGE = "documentation/WHERE_WE_ARE.md"
LEDGER = "LEDGER_CONSOLIDATED.md"


def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not os.path.exists(os.path.join(root, "palomas_orrery.py")):
        print("ERROR: palomas_orrery.py is not beside this script, so this is "
              "not the orrery's repository folder. Nothing written.")
        return 1
    texts, crlf = {}, []
    for path in sorted(set(e[0] for e in EDITS)):
        full = os.path.join(root, path)
        if not os.path.exists(full):
            print("ERROR: %s is missing. Nothing written." % path)
            return 1
        raw = open(full, "rb").read()
        if b"\r\n" in raw:
            crlf.append(path)
        texts[path] = raw.replace(b"\r\n", b"\n").decode("utf-8")

    led = texts[LEDGER]
    if "Stored drawings for the other dot-cloud shells" in led:
        print("already applied: the ledger already holds this close's item. "
              "Nothing written.")
        return 0
    taken = [int(h) for h in re.findall(r"^#### \[L-(\d+)\]", led, re.M)]
    new = max(max(taken) + 1, PLANNED)
    token = "L-%d" % PLANNED

    def renumber(s):
        return s.replace(token, "L-%d" % new).replace(
            "L:%d " % PLANNED, "L:%d " % new)

    if PAGE in texts:
        mark = MARKER.decode("ascii")
        if texts[PAGE].count(mark) != 1:
            print("ERROR: the run-record marker is not on your page exactly "
                  "once. Nothing written.")
            return 1
        cut = texts[PAGE].find(mark)
        below = texts[PAGE][cut:]
        texts[PAGE] = texts[PAGE][:cut]
    lines, skipped = [], []
    for path, label, kind, old, new_text in EDITS:
        text = texts[path]
        new_text = renumber(new_text)
        if any(ord(c) > 127 for c in new_text):
            print("ERROR: %s: %s inserts non-ASCII. Nothing written." % (path, label))
            return 1
        if kind == "line":
            found = re.findall(old, text, re.M)
            if len(found) != 1:
                print("ANCHOR FAIL: %s: %s -- the line %r matched %d times. "
                      "Nothing written." % (path, label, old, len(found)))
                return 1
            text = re.sub(old, lambda m: new_text, text, count=1, flags=re.M)
        else:
            n = text.count(old)
            if kind == "opt" and n == 0:
                skipped.append("%s: %s (already cleared)" % (path, label))
                continue
            if n != 1:
                print("ANCHOR FAIL: %s: %s -- expected 1 match, found %d. "
                      "Nothing written." % (path, label, n))
                print("  the anchor begins: %r" % old[:100])
                return 1
            text = text.replace(old, new_text)
        texts[path] = text
        lines.append("ok  %-46s %s" % (path, label))
    if PAGE in texts:
        texts[PAGE] = texts[PAGE] + below
    new_files = {}
    for path, content in NEW_FILES.items():
        content = renumber(content)
        full = os.path.join(root, path)
        if os.path.exists(full):
            have = open(full, "rb").read().replace(b"\r\n", b"\n").decode("utf-8")
            if have != content:
                print("ERROR: %s already exists and differs from this patch's "
                      "copy. Nothing written. Delete it, or tell Claude." % path)
                return 1
            lines.append("ok  %-46s already present, identical" % path)
            continue
        new_files[path] = content
    for path, text in list(texts.items()) + list(new_files.items()):
        with open(os.path.join(root, path), "w", encoding="utf-8",
                  newline="") as handle:
            handle.write(text)
    for line in lines:
        print(line)
    for path in new_files:
        print("ok  %-46s created" % path)
    for line in skipped:
        print("--  %s" % line)
    for path in crlf:
        print("note: %s was CRLF in the working copy; written LF" % path)
    page = texts[PAGE]
    above = page[:page.find(MARKER.decode())].count("\n")
    print("note: WHERE_WE_ARE.md has %d lines above the run-record marker "
          "(the cap is 130)" % above)
    print("the new item is L-%d%s" % (new, "" if new == PLANNED else
          " (L-%d was taken; renumbered)" % PLANNED))
    print("stamps updated: the ledger header; the skill's version line; "
          "PROJECT_INSTRUCTIONS.md header and anchor; the dashboard's "
          "docstring; WHERE_WE_ARE.md date line")
    print("patch applied: %d edits in %d files, and the build record."
          % (len(lines) - (len(NEW_FILES) - len(new_files)), len(texts)))
    print("")
    for line in NEXT:
        print(line)
    return 0


NEXT = [
 "NEXT:",
 "  1. Run orrery_maintenance_run.py. Expect \"23 of 23 gating checkers",
 "     passed\" and \"0 TIER-1 -- the push gate holds\". It rewrites the",
 "     skill's read plan, its manifest row (1.20) and the ledger's index.",
 "  2. Move this script, and patch_L421_6 if it is still in the root, into",
 "     documentation/; commit and push.",
 "  3. Upload skills/ledger-and-session-records/SKILL.md (Settings > Skills),",
 "     and replace the Project's instructions with PROJECT_INSTRUCTIONS.md",
 "     (now v3.91).",
]

if __name__ == "__main__":
    sys.exit(main())
